import React from "react";
import Snake from "./Snake";
import Food from "./Food";

const GameBoard = () => {
  const gridSize = 20; // 定義網格的行和列數

  // 渲染棋盤網格背景
  const renderGrid = () => {
    const cells = [];
    for (let row = 0; row < gridSize; row++) {
      for (let col = 0; col < gridSize; col++) {
        // 使用 row 和 col 來決定背景顏色（交錯的淺綠和深綠）
        const isEven = (row + col) % 2 === 0;
        const cellClass = isEven ? "cell light-green" : "cell dark-green";
        cells.push(
          <div
            key={`${row}-${col}`}
            className={cellClass}
            style={{
              gridRowStart: row + 1,
              gridColumnStart: col + 1,
            }}
          ></div>
        );
      }
    }
    return cells;
  };

  return (
    <div className="board">
      {renderGrid()} {/* 渲染背景棋盤 */}
      <Snake />      {/* 蛇的元件 */}
      <Food />       {/* 食物的元件 */}
    </div>
  );
};

export default GameBoard;
